rue}, "primary_location": {"id": "pmh:oai:arXiv.org:2304.01315", "doi": null, "is_oa": true, "landing_page_url": "http://arxiv.org/abs/2304.01315", "pdf_url": "https://arxiv.org/pdf/2304.01315", "source": {"id": "https://openalex.org/S4306400194", "display_name": "arXiv (Cornell University)", "issn_l": "2331-8422", "issn": ["2331-8422"], "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I205783295", "host_organization_name": "Cornell University", "host_organization_lineage": ["https://openalex.org/I205783295"], "host_organization_lineage_names": [], "type": "repository"}, "license": null, "license_id": null, "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "Empirical design in reinforcement learning is no small task. Running good experiments requires attention to detail and at times significant computational resources. While compute resources available per dollar have continued to grow rapidly, so have the scale of typical experiments in reinforcement learning. It is now common to benchmark agents with millions of parameters against dozens of tasks, each using the equivalent of 30 days of experience. The scale of these experiments often conflict with the need for proper statistical evidence, especially when comparing algorithms. Recent studies have highlighted how popular algorithms are sensitive to hyper-parameter settings and implementation details, and that common empirical practice leads to weak statistical evidence (Machado et al., 2018; Henderson et al., 2018). Here we take this one step further. This manuscript represents both a call to action, and a comprehensive resource for how to do good experiments in reinforcement learning. In particular, we cover: the statistical assumptions underlying common performance measures, how to properly characterize performance variation and stability, hypothesis testing, special considerations for comparing multiple agents, baseline and illustrative example construction, and how to deal with hyper-parameters and experimenter bias. Throughout we highlight common mistakes found in the literature and the statistical consequences of those in example experiments. The objective of this document is to provide answers on how we can use our unprecedented compute to do good science in reinforcement learning, as well as stay alert to potential pitfalls in our empirical design."}]", "excerpt_truncated": true, "source_sha256": "e4f32c3424fc501fbbbc935576666d3608e9fe379924021ad40633ce93b2ceb8", "verification_required": true, "topic_domain": "emergent_preferences", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.48550/arxiv.2401.12258", "doi:10.48550/arxiv.2606.04359", "openalex:W4391212055", "openalex:W7163564512", "arxiv:2401.12258", "arxiv:2304.01315"], "source_candidates": ["https://doi.org/10.48550/arxiv.2401.12258", "https://arxiv.org/pdf/2401.12258", "https://doi.org/10.48550/arxiv.2606.04359", "https://arxiv.org/pdf/2304.01315"], "source_candidate_identities": {}}

